#!/usr/bin/env python3
"""Build serial-traffic fixtures with the real tty2oled host pipeline.

1. Writes two synthetic pictures in the tty2oled text formats (our own content, because the
   upstream pictures have no licence): MDSTEST.xbm (LF, "0x00," tokens, like Pictures/XBM) and
   MDSTEST.gsc (CRLF, "0X00," tokens, like Pictures/GSC, built by c2gsc.sh).
2. Runs the exact commands from tty2oled.sh senddata() / startup (commit 50c08ac) with a plain
   file as TTYDEV, so the capture is byte-for-byte what the daemon writes:
       echo "CMDCOR,${1},${TRANSITION}" > ${TTYDEV}
       tail -n +4 "${picfnam}" | xxd -r -p > ${TTYDEV}
3. Generates firmware/test/fixtures.h for the native unit tests.

Needs bash, tail and xxd (macOS and MiSTer have them). Run from anywhere.
"""
import os
import subprocess
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(os.path.dirname(HERE))
PICS = os.path.join(HERE, "pics")
CAPTURES = os.path.join(HERE, "captures")
HEADER = os.path.join(ROOT, "firmware", "test", "fixtures.h")

W, H = 256, 64


def xbm_bytes():
    # Border, diagonal and a checker block. Values 0x0A/0x0D appear on purpose: a line reader
    # would cut the picture there.
    out = bytearray()
    for y in range(H):
        for bx in range(W // 8):
            b = 0
            for bit in range(8):
                x = bx * 8 + bit
                on = x in (0, W - 1) or y in (0, H - 1) or abs(x - 4 * y) < 2
                on = on or (96 <= x < 160 and 16 <= y < 48 and ((x // 8 + y // 8) % 2 == 0))
                if on:
                    b |= 1 << bit  # LSB is the leftmost pixel
            out.append(b)
    out[100] = 0x0A
    out[101] = 0x0D
    return bytes(out)


def gsc_bytes():
    out = bytearray()
    for y in range(H):
        for bx in range(W // 2):
            left = (bx * 2 * 16 // W) & 0x0F  # horizontal grey ramp 0..15
            right = (y * 16 // H) & 0x0F  # vertical ramp in the odd pixels
            out.append((left << 4) | right)  # high nibble is the left pixel
    out[200:206] = b"CMD\n\r\n"
    return bytes(out)


def hex_lines(data, per_line, upper):
    fmt = "0X{:02X}" if upper else "0x{:02x}"
    rows = []
    for i in range(0, len(data), per_line):
        rows.append(",".join(fmt.format(b) for b in data[i:i + per_line]) + ",")
    rows[-1] = rows[-1].rstrip(",")
    return rows


def write_pictures():
    os.makedirs(os.path.join(PICS, "XBM"), exist_ok=True)
    os.makedirs(os.path.join(PICS, "GSC"), exist_ok=True)
    xbm = ["#define _width 256", "#define _height 64", "static char _bits[] = {"]
    xbm += [" " + r for r in hex_lines(xbm_bytes(), 15, upper=False)]
    xbm += ["};", ""]
    with open(os.path.join(PICS, "XBM", "MDSTEST.xbm"), "w", newline="\n") as f:
        f.write("\n".join(xbm))
    gsc = ["//", "//", "const unsigned char _bits[8192] PROGMEM = {"]
    gsc += hex_lines(gsc_bytes(), 16, upper=True)
    gsc += ["};", ""]
    with open(os.path.join(PICS, "GSC", "MDSTEST.gsc"), "w", newline="") as f:
        # The first three lines use LF (c2gsc.sh echo), the image2lcd body uses CRLF.
        f.write("\n".join(gsc[:3]) + "\n" + "\r\n".join(gsc[3:]))


PIPELINE = r'''
set -e
TTYDEV="$1"; PICS="$2"; TRANSITION="-1"
: > "$TTYDEV"
send_startup() {
  echo "QWERTZ" >>${TTYDEV}
  echo "CMDCON,100" >>${TTYDEV}
  echo "CMDSETTIME,1759939200" >>${TTYDEV}
  echo "CMDSAVER,0,0,0" >>${TTYDEV}
}
senddata() {   # upstream: CMDCOR line, sleep, raw picture; or the bare core name
  if [ -n "$2" ]; then
    echo "CMDCOR,${1},${TRANSITION}" >>${TTYDEV}
    tail -n +4 "$2" | xxd -r -p >>${TTYDEV}
  else
    echo "${1}" >>${TTYDEV}
  fi
}
case "$3" in
  startup) send_startup ;;
  xbm) senddata MDSTEST "${PICS}/XBM/MDSTEST.xbm" ;;
  gsc) senddata MDSTEST "${PICS}/GSC/MDSTEST.gsc" ;;
  name) senddata "Atari5200" "" ;;
esac
'''


def capture(kind):
    path = os.path.join(CAPTURES, kind + ".bin")
    subprocess.run(["bash", "-c", PIPELINE, "pipeline", path, PICS, kind], check=True)
    with open(path, "rb") as f:
        return f.read()


def c_array(name, data):
    rows = [", ".join("0x{:02x}".format(b) for b in data[i:i + 16]) for i in range(0, len(data), 16)]
    body = ",\n  ".join(rows)
    return "static const uint8_t {}[{}] = {{\n  {}\n}};\n".format(name, len(data), body)


def main():
    write_pictures()
    os.makedirs(CAPTURES, exist_ok=True)
    caps = {k: capture(k) for k in ("startup", "xbm", "gsc", "name")}

    # The capture must contain exactly the payload we encoded, after the command line.
    for kind, payload in (("xbm", xbm_bytes()), ("gsc", gsc_bytes())):
        line = b"CMDCOR,MDSTEST,-1\n"
        if caps[kind] != line + payload:
            sys.exit("capture {} does not match the encoded picture".format(kind))

    with open(HEADER, "w") as f:
        f.write("// Generated by tests/fixtures/make_fixtures.py. Do not edit.\n")
        f.write("// Bytes written by the tty2oled host pipeline (echo / tail | xxd -r -p).\n")
        f.write("#pragma once\n#include <stdint.h>\n\n")
        for kind in ("startup", "xbm", "gsc", "name"):
            f.write(c_array("kCapture_" + kind, caps[kind]) + "\n")
    print("ok:", ", ".join("{}={}B".format(k, len(v)) for k, v in caps.items()))


if __name__ == "__main__":
    main()
